String _normaliseEnglishGrandMasterCardNumber(String value) {
  final cleaned = value.toLowerCase().replaceAll(RegExp(r'\s+'), '').trim();
  if (RegExp(r'^\d+$').hasMatch(cleaned)) {
    return (int.tryParse(cleaned) ?? 0).toString();
  }
  return cleaned;
}

String _normaliseEnglishGrandMasterCardName(String value) =>
    value.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), '');

int? englishGrandMasterVariantMask(String setId, String cardNumber, String cardName) {
  final key = '${setId.toLowerCase().trim()}|'
      '${_normaliseEnglishGrandMasterCardNumber(cardNumber)}|'
      '${_normaliseEnglishGrandMasterCardName(cardName)}';
  return englishGrandMasterVariantMasks[key];
}
